#!/usr/bin/env node
// Static build for shaneogren.com.
//
// Source of truth: js/data/paintings.js and js/data/paper.js.
// Generates: index.html (paintings), paper/index.html (works on paper), one
// folder per artwork (painting/<slug>/index.html, paper/<slug>/index.html),
// paper.html (redirect from the old address), sitemap.xml and robots.txt.
//
//   node build.mjs                    write the generated files into this repo
//   node build.mjs --dev --out DIR    write a complete copy of the site to DIR,
//                                     marked noindex (for a preview host)
//
// GitHub Pages serves the repo as-is (no build step there), so after editing
// the data files, run `node build.mjs` and commit the result.

import fs from "fs";
import path from "path";
import vm from "vm";
import { fileURLToPath } from "url";

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const SITE = "https://shaneogren.com";
const ARTIST = "Shane Ogren";

const args = process.argv.slice(2);
const DEV = args.includes("--dev");
const outIdx = args.indexOf("--out");
const OUT = outIdx !== -1 ? path.resolve(args[outIdx + 1]) : ROOT;
if (DEV && OUT === ROOT) {
  console.error("--dev needs --out DIR (refusing to write noindex pages into the repo)");
  process.exit(1);
}

// ── Helpers ────────────────────────────────────────────────────────────────

const esc = (s) =>
  String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

const slugify = (s) =>
  s
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/['’]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

function webpSize(file) {
  const b = fs.readFileSync(file);
  const kind = b.toString("ascii", 12, 16);
  if (kind === "VP8 ") return [b.readUInt16LE(26) & 0x3fff, b.readUInt16LE(28) & 0x3fff];
  if (kind === "VP8L") {
    const n = b.readUInt32LE(21);
    return [(n & 0x3fff) + 1, ((n >>> 14) & 0x3fff) + 1];
  }
  if (kind === "VP8X") return [b.readUIntLE(24, 3) + 1, b.readUIntLE(27, 3) + 1];
  throw new Error(`Unrecognised WebP: ${file}`);
}

function loadData(file, name) {
  const src = fs.readFileSync(path.join(ROOT, "js/data", file), "utf8");
  return vm.runInNewContext(`${src};${name}`);
}

function write(rel, content) {
  const dest = path.join(OUT, rel);
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, content);
}

// ── Sections ───────────────────────────────────────────────────────────────

const SECTIONS = [
  {
    key: "painting",
    file: "index.html",
    url: "/",
    nav: "Painting",
    plural: "Paintings",
    noun: "painting",
    works: loadData("paintings.js", "PAINTINGS"),
  },
  {
    key: "paper",
    file: "paper/index.html",
    url: "/paper/",
    nav: "Paper",
    plural: "Works on paper",
    noun: "work on paper",
    works: loadData("paper.js", "PAPER"),
  },
];

for (const sec of SECTIONS) {
  const seen = new Set();
  sec.works = sec.works.map((w, i) => {
    let slug = slugify(w.title);
    if (!slug) throw new Error(`No slug for "${w.title}"`);
    if (seen.has(slug)) slug = `${slug}-${w.year}`;
    if (seen.has(slug)) throw new Error(`Duplicate slug ${slug} in ${sec.key}`);
    seen.add(slug);

    const thumb = w.image.replace(/(images\/[^/]+\/)/, "$1thumb/");
    const [width, height] = webpSize(path.join(ROOT, w.image));
    const [tw, th] = webpSize(path.join(ROOT, thumb));
    const meta = [w.year, w.medium, w.dimensions].filter(Boolean).join(" · ");
    return {
      ...w,
      index: i,
      slug,
      url: `/${sec.key}/${slug}/`,
      full: `/${w.image}`,
      thumb: `/${thumb}`,
      width,
      height,
      tw,
      th,
      meta,
      alt: `${w.title}, ${w.medium} by ${ARTIST}, ${w.year}`,
    };
  });
}

// ── Templates ──────────────────────────────────────────────────────────────

const GENERATED = "<!-- Generated by build.mjs. Edit js/data/*.js and re-run it; do not edit this file by hand. -->";

function head({ title, description, canonical, image, extra = "" }) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  ${GENERATED}
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${esc(title)}</title>
  <meta name="description" content="${esc(description)}">${DEV ? '\n  <meta name="robots" content="noindex, nofollow">' : ""}
  <link rel="canonical" href="${SITE}${canonical}">
  <meta property="og:type" content="website">
  <meta property="og:site_name" content="${ARTIST}">
  <meta property="og:title" content="${esc(title)}">
  <meta property="og:description" content="${esc(description)}">
  <meta property="og:url" content="${SITE}${canonical}">
  <meta property="og:image" content="${SITE}${image}">
  <meta name="twitter:card" content="summary_large_image">
  <link rel="icon" type="image/x-icon" href="/favicon.ico">
  <link rel="icon" type="image/png" sizes="32x32" href="/favicon-32x32.png">
  <link rel="apple-touch-icon" href="/apple-touch-icon.png">
  <link rel="stylesheet" href="/css/style.css">${extra}
</head>
<body>
`;
}

function header(activeKey) {
  const link = (href, label, key) =>
    `<a href="${href}"${key === activeKey ? ' class="active"' : ""}>${label}</a>`;
  return `
  <header>
    <a href="/" class="site-title">${ARTIST}</a>
    <nav>
      ${link("/", "Painting", "painting")}
      ${link("/paper/", "Paper", "paper")}
      ${link("/contact.html", "Contact", "contact")}
      ${link("/about.html", "About", "about")}
    </nav>
  </header>
`;
}

function galleryPage(sec) {
  const years = sec.works.map((w) => w.year);
  const media = [...new Set(sec.works.map((w) => w.medium))];
  const description =
    `${sec.plural} by ${ARTIST}, ${Math.min(...years)}–${Math.max(...years)}: ` +
    `${sec.works.length} works in ${media.slice(0, 3).join(", ")}${media.length > 3 ? " and more" : ""}.`;

  const items = sec.works
    .map(
      (w) => `    <a class="gallery-item" href="${w.url}" data-full="${w.full}" data-w="${w.width}" data-h="${w.height}" data-title="${esc(w.title)}" data-meta="${esc(w.meta)}">
      <img src="${w.thumb}" alt="${esc(w.alt)}" width="${w.tw}" height="${w.th}" loading="lazy">
      <div class="artwork-info">
        <div class="artwork-title">${esc(w.title)}</div>
        <div class="artwork-meta">${esc(w.meta)}</div>
      </div>
    </a>`
    )
    .join("\n");

  return (
    head({
      title: `${ARTIST} — ${sec.nav}`,
      description,
      canonical: sec.url,
      image: sec.works[0].full,
    }) +
    header(sec.key) +
    `
  <h1 class="visually-hidden">${sec.plural} by ${ARTIST}</h1>

  <div id="gallery" class="gallery">
${items}
  </div>

  <script src="/js/viewer.js"></script>
  <script src="/js/main.js"></script>

</body>
</html>
`
  );
}

function artworkPage(sec, w) {
  const n = sec.works.length;
  const prev = sec.works[(w.index - 1 + n) % n];
  const next = sec.works[(w.index + 1) % n];
  const title = `${w.title} (${w.year}) — ${ARTIST}`;
  const description =
    `“${w.title}”, ${w.year}. ${cap(w.medium)}${w.dimensions ? `, ${w.dimensions}` : ""}. ` +
    `A ${sec.noun} by ${ARTIST}.`;

  const ld = {
    "@context": "https://schema.org",
    "@type": "VisualArtwork",
    name: w.title,
    url: `${SITE}${w.url}`,
    image: `${SITE}${w.full}`,
    dateCreated: String(w.year),
    artMedium: w.medium,
    artform: sec.key === "painting" ? "Painting" : "Work on paper",
    creator: { "@type": "Person", name: ARTIST, url: `${SITE}/` },
  };
  if (w.dimensions) ld.size = w.dimensions;

  return (
    head({
      title,
      description,
      canonical: w.url,
      image: w.full,
      extra: `\n  <script type="application/ld+json">${JSON.stringify(ld).replace(/</g, "\\u003c")}</script>`,
    }) +
    header(sec.key) +
    `
  <main class="artwork">
    <div id="artwork-stage" class="artwork-stage">
      <img id="artwork-img" src="${w.full}" alt="${esc(w.alt)}" width="${w.width}" height="${w.height}">
    </div>

    <div class="artwork-caption">
      <h1>${esc(w.title)}</h1>
      <p>${esc(w.meta)}</p>
    </div>

    <nav class="artwork-nav" aria-label="More ${sec.plural.toLowerCase()}">
      <a id="artwork-prev" href="${prev.url}" rel="prev">‹ ${esc(prev.title)}</a>
      <a href="${sec.url}">All ${sec.plural.toLowerCase()}</a>
      <a id="artwork-next" href="${next.url}" rel="next">${esc(next.title)} ›</a>
    </nav>
  </main>

  <script src="/js/viewer.js"></script>
  <script src="/js/artwork.js"></script>

</body>
</html>
`
  );
}

function sitemap() {
  const url = (loc, images = []) =>
    `  <url>\n    <loc>${SITE}${loc}</loc>\n` +
    images.map((i) => `    <image:image><image:loc>${SITE}${i}</image:loc></image:image>\n`).join("") +
    `  </url>`;
  const rows = [];
  for (const sec of SECTIONS) rows.push(url(sec.url));
  rows.push(url("/about.html"), url("/contact.html"));
  for (const sec of SECTIONS) for (const w of sec.works) rows.push(url(w.url, [w.full]));
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">
${rows.join("\n")}
</urlset>
`;
}

// ── Write ──────────────────────────────────────────────────────────────────

if (OUT !== ROOT) {
  fs.mkdirSync(OUT, { recursive: true });
  for (const name of [
    "css", "js", "images", "about.html", "contact.html",
    "favicon.ico", "favicon-16x16.png", "favicon-32x32.png", "apple-touch-icon.png",
  ]) {
    fs.cpSync(path.join(ROOT, name), path.join(OUT, name), { recursive: true });
  }
  if (DEV) {
    for (const name of ["about.html", "contact.html"]) {
      const p = path.join(OUT, name);
      fs.writeFileSync(
        p,
        fs.readFileSync(p, "utf8").replace("<head>", '<head>\n  <meta name="robots" content="noindex, nofollow">')
      );
    }
  }
}

// Remove artwork pages from a previous build so renamed titles leave no orphans.
for (const sec of SECTIONS) fs.rmSync(path.join(OUT, sec.key), { recursive: true, force: true });

let pages = 0;
for (const sec of SECTIONS) {
  write(sec.file, galleryPage(sec));
  for (const w of sec.works) {
    write(`${sec.key}/${w.slug}/index.html`, artworkPage(sec, w));
    pages++;
  }
}

// The paper gallery used to live at /paper.html; keep that address working.
write(
  "paper.html",
  `<!DOCTYPE html>
<html lang="en">
<head>
  ${GENERATED}
  <meta charset="UTF-8">
  <title>${ARTIST} — Paper</title>
  <link rel="canonical" href="${SITE}/paper/">
  <meta http-equiv="refresh" content="0; url=/paper/">
  <script>location.replace("/paper/" + location.hash);</script>
</head>
<body>
  <p><a href="/paper/">Works on paper</a></p>
</body>
</html>
`
);

write("sitemap.xml", sitemap());
write(
  "robots.txt",
  DEV
    ? "# Preview copy. The real site is https://shaneogren.com\nUser-agent: *\nDisallow: /\n"
    : `User-agent: *\nAllow: /\n\nSitemap: ${SITE}/sitemap.xml\n`
);

console.log(`${DEV ? "DEV " : ""}build -> ${OUT}: 2 gallery pages, ${pages} artwork pages, sitemap.xml, robots.txt`);
